    func testOpenBookClub() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")

        // Try to find and click the Cancel button to dismiss the dialog
        let cancelButton = app.buttons["Cancel"]
        if cancelButton.exists {
            cancelButton.tap()
        }

        // Wait a moment for the dialog to close
        sleep(1)

        // Try to find the Book Club room and tap it
        let bookClubRoom = app.staticTexts["Book Club"]
        if bookClubRoom.exists {
            bookClubRoom.tap()
        }
    }
}
